create function private.construction_point(p jsonb) returns boolean language sql immutable set search_path='' as $$
 select jsonb_typeof(p)='object' and (select count(*) from jsonb_object_keys(p))=2 and p ?& array['x','y'] and jsonb_typeof(p->'x')='number' and jsonb_typeof(p->'y')='number' and (p->>'x')::numeric=trunc((p->>'x')::numeric) and (p->>'y')::numeric=trunc((p->>'y')::numeric) and (p->>'x')::numeric between 0 and 255 and (p->>'y')::numeric between 0 and 255;
$$;
alter function private.sim_validate(jsonb,public.worlds) rename to sim_validate_v7;
create function private.sim_validate(s jsonb,w public.worlds) returns void language plpgsql set search_path='' as $$
declare c jsonb;p jsonb;b jsonb;spec jsonb;l jsonb;h jsonb;a jsonb;n text;loc text;lot jsonb;rows jsonb:='[]';people jsonb:='[]';base jsonb;jobs jsonb:='[]';t bigint;days integer;busy text[]:=array[]::text[];siteids text[]:=array[]::text[];yardids text[]:=array[]::text[];haulids text[]:=array[]::text[];qty numeric;cap numeric;required numeric;capacity integer;bw integer;bh integer;cx integer;cy integer;age bigint;protected boolean;
begin
 if (s->>'schemaVersion')::integer between 2 and 7 then perform private.sim_validate_v7(s,w);return;end if;
 if s->'schemaVersion' is distinct from '8'::jsonb or s->>'engineVersion' is distinct from 'we-sim-6' or (select count(*) from jsonb_object_keys(s))<>23 then raise exception 'INVALID_SAVE' using errcode='22023';end if;
 c:=s->'construction';t:=(s->>'tick')::bigint;
 if jsonb_typeof(c) is distinct from 'object' or (select count(*) from jsonb_object_keys(c))<>6 or not(c ?& array['version','sites','yards','hauls','builders','sequence']) or c->'version' is distinct from '1'::jsonb or jsonb_typeof(c->'sequence') is distinct from 'number' or (c->>'sequence')::numeric not between 0 and 1e12 or (c->>'sequence')::numeric<>trunc((c->>'sequence')::numeric) then raise exception 'INVALID_CONSTRUCTION' using errcode='22023';end if;
 foreach n in array array['sites','yards','hauls','builders'] loop if jsonb_typeof(c->n) is distinct from 'array' then raise exception 'INVALID_CONSTRUCTION' using errcode='22023';end if;end loop;
 if jsonb_array_length(c->'sites')>256 or jsonb_array_length(c->'yards')>32 or jsonb_array_length(c->'hauls')>20 or jsonb_array_length(c->'builders')>20 then raise exception 'INVALID_CONSTRUCTION' using errcode='22023';end if;
 for p in select value from jsonb_array_elements(c->'sites') loop
  if jsonb_typeof(p) is distinct from 'object' or (select count(*) from jsonb_object_keys(p))<>7 or not(p ?& array['id','entrance','status','workDone','workRequired','createdTick','completedTick']) or not coalesce(private.construction_point(p->'entrance'),false) then raise exception 'INVALID_SITE' using errcode='22023';end if;
  perform (p->>'id')::uuid;if p->>'id'=any(siteids) then raise exception 'INVALID_SITE' using errcode='22023';end if;siteids:=array_append(siteids,p->>'id');
  select value into b from jsonb_array_elements(s->'planning'->'buildings') where value->>'id'=p->>'id';
  select cc.spec into spec from private.construction_catalog cc where cc.id=b->>'buildingId';
  select greatest(180,coalesce(sum((v->>'quantity')::numeric),0)*180) into required from jsonb_array_elements(spec->'materials') v;
  foreach n in array array['workDone','workRequired','createdTick'] loop if jsonb_typeof(p->n) is distinct from 'number' or (p->>n)::numeric<>trunc((p->>n)::numeric) or (p->>n)::numeric not between 0 and 1e12 then raise exception 'INVALID_SITE' using errcode='22023';end if;end loop;
  if b is null or spec is null or p->>'status' is null or p->>'status' not in ('active','paused','complete','cancelled') or (p->>'workRequired')::numeric<>required or (p->>'workDone')::numeric>required or (p->>'createdTick')::bigint not between (b->>'createdTick')::bigint and t or ((p->>'status'='complete') is distinct from ((p->>'workDone')::numeric=required)) then raise exception 'INVALID_SITE' using errcode='22023';end if;
  select case when (b->>'rotation')::integer%2=0 then pc.width else pc.height end,case when (b->>'rotation')::integer%2=0 then pc.height else pc.width end into bw,bh from private.planning_catalog pc where pc.id=b->>'buildingId';cx:=(p->'entrance'->>'x')::integer;cy:=(p->'entrance'->>'y')::integer;
  if not(((cx=(b->>'x')::integer-1 or cx=(b->>'x')::integer+bw) and cy between (b->>'y')::integer and (b->>'y')::integer+bh-1) or ((cy=(b->>'y')::integer-1 or cy=(b->>'y')::integer+bh) and cx between (b->>'x')::integer and (b->>'x')::integer+bw-1)) or (p->>'workDone')::numeric>(coalesce((p->>'completedTick')::bigint,t)-(p->>'createdTick')::bigint)*2 then raise exception 'INVALID_SITE' using errcode='22023';end if;
  if p->>'status'='complete' then if jsonb_typeof(p->'completedTick') is distinct from 'number' or (p->>'completedTick')::numeric<>trunc((p->>'completedTick')::numeric) or (p->>'completedTick')::bigint not between (p->>'createdTick')::bigint and t then raise exception 'INVALID_SITE' using errcode='22023';end if;elsif p->'completedTick' is distinct from 'null'::jsonb or (p->>'workDone')::numeric>(t-(p->>'createdTick')::bigint)*2 then raise exception 'INVALID_SITE' using errcode='22023';end if;
 end loop;
 for p in select value from jsonb_array_elements(c->'yards') loop
  if jsonb_typeof(p) is distinct from 'object' or (select count(*) from jsonb_object_keys(p))<>2 or not(p ?& array['id','cell']) or not coalesce(private.construction_point(p->'cell'),false) then raise exception 'INVALID_YARD' using errcode='22023';end if;
  perform (p->>'id')::uuid;if p->>'id'=any(yardids) or p->>'id'=any(siteids) or p->'cell'=s->'survival'->'depot' or exists(select 1 from jsonb_array_elements(c->'yards') q where q->>'id'<>p->>'id' and q->'cell'=p->'cell') then raise exception 'INVALID_YARD' using errcode='22023';end if;yardids:=array_append(yardids,p->>'id');
 end loop;
 for p in select value from jsonb_array_elements(c->'builders') loop
  if jsonb_typeof(p) is distinct from 'object' or (select count(*) from jsonb_object_keys(p))<>2 or not(p ?& array['citizenId','siteId']) or p->>'citizenId' is null or p->>'citizenId'=any(busy) or not exists(select 1 from jsonb_array_elements(c->'sites') q where q->>'id'=p->>'siteId' and q->>'status' in ('active','paused')) or not exists(select 1 from jsonb_array_elements(s->'workforce'->'workers') q where q->>'citizenId'=p->>'citizenId' and q->>'roleId'='J008' and q->'qualified'='true'::jsonb and q->'training'='null'::jsonb and q->'assignment'='null'::jsonb) then raise exception 'INVALID_BUILDER' using errcode='22023';end if;
  if (select count(*) from jsonb_array_elements(c->'builders') q where q->>'siteId'=p->>'siteId')>2 then raise exception 'INVALID_BUILDER' using errcode='22023';end if;busy:=array_append(busy,p->>'citizenId');
 end loop;
 for h in select value from jsonb_array_elements(c->'hauls') loop
  if jsonb_typeof(h) is distinct from 'object' or (select count(*) from jsonb_object_keys(h))<>8 or not(h ?& array['id','citizenId','lotId','quantity','source','destination','phase','cargo']) or (h->>'id')!~'^haul-[1-9][0-9]*$' or h->>'id' is null or h->>'id'=any(haulids) or substring(h->>'id' from 6)::bigint>(c->>'sequence')::bigint or h->>'citizenId' is null or h->>'citizenId'=any(busy) or not exists(select 1 from jsonb_array_elements(s->'citizens') q where q->>'id'=h->>'citizenId') or jsonb_typeof(h->'quantity') is distinct from 'number' or (h->>'quantity')::numeric<=0 or (h->>'quantity')::numeric>3 or h->>'phase' is null or h->>'phase' not in ('pickup','delivery','blocked') or h->>'source'=h->>'destination' then raise exception 'INVALID_HAUL' using errcode='22023';end if;
  foreach n in array array['source','destination'] loop loc:=h->>n;if loc is null or not(loc='depot' or substring(loc from 6)=any(yardids) and loc like 'yard:%' or substring(loc from 6)=any(siteids) and loc like 'site:%') then raise exception 'INVALID_HAUL' using errcode='22023';end if;end loop;
  select value into lot from jsonb_array_elements(s->'survival'->'lots') where value->>'id'=coalesce(h->>'cargo',h->>'lotId');
  if lot is null or (h->'cargo' is distinct from 'null'::jsonb and (jsonb_typeof(h->'cargo') is distinct from 'string' or lot->>'location'<>'citizen:'||(h->>'citizenId') or lot->'quantity' is distinct from h->'quantity' or h->>'phase'='pickup')) or (h->'cargo'='null'::jsonb and (lot->>'location'<>h->>'source' or h->>'phase'='delivery')) then raise exception 'INVALID_HAUL' using errcode='22023';end if;
  busy:=array_append(busy,h->>'citizenId');haulids:=array_append(haulids,h->>'id');
 end loop;
 if exists(select 1 from jsonb_array_elements(s->'survival'->'jobs') j where j->>'citizenId'=any(busy)) or exists(select 1 from jsonb_array_elements(s->'workforce'->'workers') alias_p(value) where alias_p.value->>'citizenId'=any(busy) and (alias_p.value->'training'<>'null'::jsonb or alias_p.value->'assignment'<>'null'::jsonb)) then raise exception 'DUPLICATE_JOB' using errcode='22023';end if;
 for l in select value from jsonb_array_elements(s->'survival'->'lots') loop
  select cr.ttl_days into days from private.construction_resources cr where cr.id=l->>'resource';if not found then raise exception 'INVALID_RESOURCE' using errcode='22023';end if;
  loc:=l->>'location';protected:=false;
  if loc='depot' then null;
  elsif substring(loc from 6)=any(yardids) and loc like 'yard:%' then null;
  elsif substring(loc from 6)=any(siteids) and loc like 'site:%' then
   select value into p from jsonb_array_elements(c->'sites') where 'site:'||(value->>'id')=loc;
   select value into b from jsonb_array_elements(s->'planning'->'buildings') where value->>'id'=p->>'id';
   select cc.spec into spec from private.construction_catalog cc where cc.id=b->>'buildingId';
   if p->>'status' in ('active','paused') and (l->>'quantity')::numeric>0 and not exists(select 1 from jsonb_array_elements(spec->'materials') m where m->>'resource'=l->>'resource') then raise exception 'INVALID_BOM' using errcode='22023';end if;
   if p->>'status'='complete' and (l->>'quantity')::numeric>0 then
    if b->>'buildingId'='B010' then if not exists(select 1 from private.construction_resources cr where cr.id=l->>'resource' and cr.storage='Kho lương thực') then raise exception 'INVALID_STORAGE' using errcode='22023';end if;protected:=not exists(select 1 from jsonb_array_elements(spec->'staffing') need where (select count(*) from jsonb_array_elements(s->'workforce'->'workers') worker where worker->'assignment'->>'siteId'=p->>'id' and worker->>'roleId'=need->>'roleId' and (worker->'qualified'='true'::jsonb or worker->'training'->>'phase' in ('studying','practice','outbound')) and exists(select 1 from jsonb_array_elements(s->'citizens') person where person->>'id'=worker->>'citizenId' and person->>'status'='idle' and person->'x'=p->'entrance'->'x' and person->'y'=p->'entrance'->'y'))<(need->>'required')::integer);
    elsif b->>'buildingId'='B011' then if days is not null then raise exception 'INVALID_STORAGE' using errcode='22023';end if;
    elsif b->>'buildingId'='B118' then if l->>'resource'<>'R213' then raise exception 'INVALID_STORAGE' using errcode='22023';end if;protected:=not exists(select 1 from jsonb_array_elements(spec->'staffing') need where (select count(*) from jsonb_array_elements(s->'workforce'->'workers') worker where worker->'assignment'->>'siteId'=p->>'id' and worker->>'roleId'=need->>'roleId' and (worker->'qualified'='true'::jsonb or worker->'training'->>'phase' in ('studying','practice','outbound')) and exists(select 1 from jsonb_array_elements(s->'citizens') person where person->>'id'=worker->>'citizenId' and person->>'status'='idle' and person->'x'=p->'entrance'->'x' and person->'y'=p->'entrance'->'y'))<(need->>'required')::integer);
    elsif b->>'buildingId'='B007' then if (l->>'resource') not in ('R001','R002','R003','R008','R167','R009','R062') then raise exception 'INVALID_STORAGE' using errcode='22023';end if;else raise exception 'INVALID_STORAGE' using errcode='22023';end if;
   end if;
  elsif loc like 'citizen:%' then if not exists(select 1 from jsonb_array_elements(c->'hauls') alias_h(value) where alias_h.value->>'cargo'=l->>'id' and loc='citizen:'||(alias_h.value->>'citizenId')) and not exists(select 1 from jsonb_array_elements(s->'survival'->'jobs') j where j->'cargo' ? (l->>'id') and loc='citizen:'||(j->>'citizenId')) then raise exception 'INVALID_CARGO' using errcode='22023';end if;
  else raise exception 'INVALID_LOCATION' using errcode='22023';end if;
  age:=(l->>'ageTicks')::bigint;
  if days is null then if l->'expiresTick' is distinct from 'null'::jsonb or l->'spoiled' is distinct from 'false'::jsonb then raise exception 'INVALID_LOT' using errcode='22023';end if;
  elsif l->'spoiled' is distinct from to_jsonb(age>=days*1800) or (age<days*1800 and l->'expiresTick' is distinct from to_jsonb(t+days*1800-age) and not(protected and l->'expiresTick'='null'::jsonb)) then raise exception 'INVALID_LOT' using errcode='22023';end if;
  if (select coalesce(sum((alias_h.value->>'quantity')::numeric),0) from jsonb_array_elements(c->'hauls') alias_h(value) where alias_h.value->'cargo'='null'::jsonb and alias_h.value->>'lotId'=l->>'id')>(l->>'quantity')::numeric then raise exception 'INVALID_RESERVATION' using errcode='22023';end if;
  -- Validation-only normalization. Stored payload/checksum/history always retain the true lots.
  lot:=l;if loc not like 'citizen:%' or exists(select 1 from jsonb_array_elements(c->'hauls') alias_h(value) where alias_h.value->>'cargo'=l->>'id') then lot:=jsonb_set(lot,'{location}','"depot"'::jsonb);end if;
  if (l->>'resource') not in ('R001','R002','R003','R004','R005','R006','R007','R008','R009','R030','R031','R032','R033','R058','R059','R061','R062','R067','R125','R167','R213') then lot:=lot||'{"resource":"R058","expiresTick":null,"spoiled":false}'::jsonb;elsif days is not null and protected and l->'expiresTick'='null'::jsonb then lot:=jsonb_set(lot,'{expiresTick}',to_jsonb(t+greatest(0,days*1800-age)));end if;
  rows:=rows||jsonb_build_array(lot);
 end loop;
 for p in select value from jsonb_array_elements(c->'yards') loop select coalesce(sum((alias_l.value->>'quantity')::numeric),0) into qty from jsonb_array_elements(s->'survival'->'lots') alias_l(value) where alias_l.value->>'location'='yard:'||(p->>'id');if qty>60 then raise exception 'STORAGE_FULL' using errcode='22023';end if;end loop;
 for p in select value from jsonb_array_elements(c->'sites') loop
  select value into b from jsonb_array_elements(s->'planning'->'buildings') where value->>'id'=p->>'id';select cc.spec into spec from private.construction_catalog cc where cc.id=b->>'buildingId';
  if p->>'status' in ('active','paused') then for a in select value from jsonb_array_elements(spec->'materials') loop select coalesce(sum((v->>'quantity')::numeric),0) into qty from jsonb_array_elements(s->'survival'->'lots') v where v->>'location'='site:'||(p->>'id') and v->>'resource'=a->>'resource';if qty>(a->>'quantity')::numeric then raise exception 'INVALID_BOM' using errcode='22023';end if;end loop;end if;
  if p->>'status'<>'cancelled' then select coalesce(sum((alias_l.value->>'quantity')::numeric),0) into qty from jsonb_array_elements(s->'survival'->'lots') alias_l(value) where alias_l.value->>'location'='site:'||(p->>'id');if p->>'status'='complete' then cap:=case when b->>'buildingId'='B007' then 30 else coalesce((spec->>'capacity')::numeric,0) end;else select coalesce(sum((m->>'quantity')::numeric),0) into cap from jsonb_array_elements(spec->'materials') m;end if;if qty>cap then raise exception 'STORAGE_FULL' using errcode='22023';end if;end if;
 end loop;
 for p in select value from jsonb_array_elements(s->'citizens') loop
  if p->'homeId'<>'null'::jsonb then
   select value into a from jsonb_array_elements(c->'sites') where value->>'id'=p->>'homeId' and value->>'status'='complete';select value into b from jsonb_array_elements(s->'planning'->'buildings') where value->>'id'=a->>'id';
   capacity:=case b->>'buildingId' when 'B006' then 5 when 'B130' then 5 when 'B141' then 6 when 'B150' then 8 when 'B059' then 12 when 'B157' then 14 when 'B163' then 35 when 'B166' then 45 else 0 end;
   if capacity=0 or (select count(*) from jsonb_array_elements(s->'citizens') q where q->>'homeId'=p->>'homeId')>capacity then raise exception 'INVALID_HOME' using errcode='22023';end if;
  end if;people:=people||jsonb_build_array(jsonb_set(p,'{homeId}','null'::jsonb));
 end loop;
 for p in select value from jsonb_array_elements(s->'survival'->'jobs') loop
  if p->>'kind'='water' or p->>'kind'='process' and p->>'recipeId' not in ('F001','F002') then p:=jsonb_set(p,'{kind}','"gather"'::jsonb);end if;jobs:=jobs||jsonb_build_array(p);
 end loop;
 base:=(s-'construction')||'{"schemaVersion":7,"engineVersion":"we-sim-5"}'::jsonb;base:=jsonb_set(jsonb_set(jsonb_set(base,'{survival,lots}',rows),'{citizens}',people),'{survival,jobs}',jobs);perform private.sim_validate_v7(base,w);
end;$$;
revoke all on function private.construction_point(jsonb),private.sim_validate(jsonb,public.worlds),private.sim_validate_v7(jsonb,public.worlds) from public,anon,authenticated;
commit;
